        "requiredReplacement": "補足 layer、buffer、overlay、network 的資料與操作差異。",
        "replacementContent": "GIS 圖層是把不同類型的空間資料分開管理，例如道路、人口、坡度、河川與土地利用各自是一個 layer。若問題是『距河川 200 公尺以外』或『距學校 500 公尺內』，使用 buffer 建立距離範圍；若要同時符合低坡度、避開保育區並接近人口中心，使用 overlay 疊合多個圖層；若要找道路最短路徑或服務範圍，才使用 network。操作名稱不能互換，必須先看題目要求的空間關係。",
