        "requiredReplacement": "補足適宜性分析不是單一條件最佳化，而是多條件篩選與權衡。",
        "replacementContent": "Suitability analysis 通常先排除不符合硬性限制的區域，再比較剩餘地點的多項條件，例如道路可達性、服務人口、坡度、環境敏感度與土地成本。『離道路最近』不一定是最佳答案，因為可能同時落在洪水風險區或保育區。題目若給權重、門檻或限制，應分清哪些是不能違反的條件，哪些是可以互相權衡的評估項目。",
