        "requiredReplacement": "補足空間解析度、更新時間、缺漏與尺度對 GIS 結果的限制。",
        "replacementContent": "GIS 的分析結果不會自動等於現實。空間解析度太粗，可能看不出小尺度道路或人口差異；資料更新太慢，可能漏掉新道路或土地利用變化；資料缺漏、分類方式與比例尺不同，也會使圖層疊合產生偏差。因此看到 GIS 結果時，還要檢查資料來源、時間、尺度、解析度與完整性，避免把精確的地圖外觀誤當成精確結論。",
