        "requiredReplacement": "補足 GIS 是決策工具，並把環境、社會、經濟與公平納入永續權衡。",
        "replacementContent": "GIS 可以把條件視覺化、計算距離與比較候選地，但它不會替社會決定什麼是唯一合理的方案。永續選址要同時考量環境影響、居民安全、服務公平、建設與維護成本，以及長期氣候與人口變化。若一個地點最省錢卻讓弱勢社區承擔污染或風險，仍需重新檢討。學測整合題常要求先完成空間分析，再評估資料限制與不同群體的長期利益。",
